// Recoit le payload thruuu (callback) et produit un brief editorial flat.
// Le payload est dans $input.first().json.body (Wait node webhook mode).
const payload = $input.first().json.body || $input.first().json;

const organic = payload.organic || payload.results || payload.organic_results || [];

const top = organic.slice(0, 10).map((r, i) => ({
  position: r.position || r.rank || i + 1,
  title: r.title || null,
  url: r.url || r.link || null,
  meta_description: r.description || r.meta_description || null,
  word_count: r.word_count || r.words || null,
}));

const wordCounts = top.map(t => t.word_count).filter(Boolean);
const avgWc = wordCounts.length ? Math.round(wordCounts.reduce((a, b) => a + b, 0) / wordCounts.length) : null;

return [{
  json: {
    keyword: payload.keyword || payload.query || null,
    country: payload.country || null,
    language: payload.language || null,
    device: payload.device || null,
    target_word_count: avgWc,
    competitors_count: top.length,
    top_titles: top.map(t => t.title).filter(Boolean).join(' | '),
    top_urls: top.map(t => t.url).filter(Boolean).join(' | '),
    related_searches: (payload.related_searches || []).slice(0, 10).join(' | '),
    people_also_ask: (payload.people_also_ask || payload.similar_questions || payload.paa || []).slice(0, 10).map(q => typeof q === 'string' ? q : (q.question || q.text || '')).filter(Boolean).join(' | '),
    top_topics: (payload.top_topics || payload.topics || []).slice(0, 20).map(t => typeof t === 'string' ? t : (t.topic || t.term || '')).filter(Boolean).join(' | '),
    analyzed_at: new Date().toISOString(),
    serp_id: payload.id || payload._id || null,
  }
}];

